CREATE FUNCTION orgtree.record_capture_docket_question_links() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,orgtree AS $fn$
BEGIN
  IF current_setting('orgtree.capture', true) = 'off' THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'org' AS entity, 'work_summary' AS entity_id FROM new_rows r WHERE true
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'org' AS entity, 'work_summary' AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT 'org' AS entity, 'work_summary' AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'org' AS entity, 'work_summary' AS entity_id FROM old_rows r WHERE true
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END
$fn$;

